const grid = document.querySelector('#project-grid');
function projectCard(p,i){return `<a class="collection-slide" href="/projects/${p.slug}/" aria-label="Explore ${p.name}"><div class="collection-image" style="background:${p.color}"><span class="collection-stamp">${String(i+1).padStart(2,'0')} / ${p.label}</span><img src="/assets/${p.image}" alt="${p.name} interface" loading="lazy"><span class="collection-open" aria-hidden="true">+</span></div><div class="collection-caption"><div><h3>${p.name}</h3><p>${p.category}</p></div><span>Explore project</span></div></a>`}
if(grid){
 grid.innerHTML=projects.map(projectCard).join('');
 document.querySelector('#collection-index').innerHTML=projects.map((p,i)=>`<button type="button" class="collection-jump${i===0?' is-active':''}" data-project="${i}"${i===0?' aria-current="true"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${p.name}</span><span class="collection-dot" aria-hidden="true"></span></button>`).join('');
 initCollection();
}
